int is_connected(int count) {
    if (count == 0) return 0;
    memset(visited, 0, sizeof(visited));
    int stack[15], top = 0;
    int start = -1;
    for (int i = 0; i < n; i++) {
        if (selected[i]) {
            start = i;
            break;
        }
    }
    if (start == -1) return 0;
    stack[top++] = start;
    visited[start] = 1;
    int seen = 1;
    while (top > 0) {
        int cur = stack[--top];
        for (int i = 0; i < n; i++) {
            if (selected[i] && !visited[i] && is_adjacent(cur, i)) {
                visited[i] = 1;
                stack[top++] = i;
                seen++;
            }
        }
    }
    return seen == count;
}

int compute_surface_area(int count) {
    int exposed = 0;
    for (int i = 0; i < n; i++) {
        if (!selected[i]) continue;
        int faces = 6;
        for (int j = 0; j < n; j++) {
            if (i != j && selected[j] && is_adjacent(i, j)) {
                faces--;
            }
        }
        exposed += faces;
    }
    return exposed;
}

void backtrack(int idx, int count) {
    if (count == k) {
        if (is_connected(count)) {
            int area = compute_surface_area(count);
            if (area < min_area) min_area = area;
