static inline int abs_i(int a) { return a < 0 ? -a : a; }

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;

    Point *p = (Point*)malloc(sizeof(Point) * n);
    for (int i = 0; i < n; ++i) {
        scanf("%d %d %d", &p[i].x, &p[i].y, &p[i].z);
    }

    /* Build adjacency: cubes are connected if Manhattan distance is 1 */
    unsigned int *adj = (unsigned int*)calloc(n, sizeof(unsigned int));
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            int d = abs_i(p[i].x - p[j].x) + abs_i(p[i].y - p[j].y) + abs_i(p[i].z - p[j].z);
            if (d == 1) {
                adj[i] |= (1u << j);
                adj[j] |= (1u << i);
            }
        }
    }

    int maxMask = 1 << n;
    int *cnt = (int*)malloc(sizeof(int) * maxMask);
    int *edges = (int*)malloc(sizeof(int) * maxMask);
    unsigned int *unionAdj = (unsigned int*)malloc(sizeof(unsigned int) * maxMask);
    char *connected = (char*)calloc(maxMask, sizeof(char));

    cnt[0] = 0;
    edges[0] = 0;
    unionAdj[0] = 0;
    connected[0] = 0;

    int bestEdges = -1;

    for (int mask = 1; mask < maxMask; ++mask) {
        int b = mask & -mask;
        int v = 0;
        while ((1 << v) != b) ++v;
        int prev = mask ^ b;

        cnt[mask] = cnt[prev] + 1;
        unionAdj[mask] = unionAdj[prev] | adj[v];

        int addEdges = 0;
        unsigned int t = adj[v] & (unsigned int)prev;
        while (t) {
            t &= (t - 1);
            ++addEdges;
        }
        edges[mask] = edges[prev] + addEdges;

        if (cnt[mask] == 1) {
            connected[mask] = 1;
        } else {
            /* connected iff the added vertex touches previous subset
               and previous subset is connected */
            connected[mask] = connected[prev] && ((adj[v] & (unsigned int)prev) != 0);
        }

        if (cnt[mask] == k && connected[mask]) {
            if (edges[mask] > bestEdges) bestEdges = edges[mask];
        }
    }

    /* Surface area = 6*k - 2*(number of shared faces) */
    int answer = 6 * k - 2 * bestEdges;
    printf("%d\n", answer);

    free(p);
    free(adj);
    free(cnt);
    free(edges);
    free(unionAdj);
    free(connected);
    return 0;
}

