struct Cube {
    int x, y, z;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<Cube> cubes(n);
    for (int i = 0; i < n; i++) {
        cin >> cubes[i].x >> cubes[i].y >> cubes[i].z;
    }

    // Map coordinates to index
    map<tuple<int,int,int>, int> idx;
    for (int i = 0; i < n; i++) {
        idx[{cubes[i].x, cubes[i].y, cubes[i].z}] = i;
    }

    // Build adjacency list for face-adjacent cubes
    vector<vector<int>> adj(n);
    int dx[] = {1, -1, 0, 0, 0, 0};
    int dy[] = {0, 0, 1, -1, 0, 0};
    int dz[] = {0, 0, 0, 0, 1, -1};

    for (int i = 0; i < n; i++) {
        for (int d = 0; d < 6; d++) {
            int nx = cubes[i].x + dx[d];
            int ny = cubes[i].y + dy[d];
            int nz = cubes[i].z + dz[d];
            auto it = idx.find({nx, ny, nz});
            if (it != idx.end()) {
                adj[i].push_back(it->second);
            }
        }
    }

    // BFS over subsets: state = (mask, last_node). Mask up to 2^15 if n small, but n can be up to 20.
    // Use DP over subsets with bitmask for small n.
    // If n <= 20, use DP; otherwise n is small because k <= n <= 20 from constraints.

    int fullMask = (1 << n);
    const int INF = 1e9;
    vector<vector<int>> dp(fullMask, vector<int>(n, INF));

    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 6; // single cube surface area
    }

    for (int mask = 1; mask < fullMask; mask++) {
        int pop = __builtin_popcount(mask);
        if (pop > k) continue;
        for (int last = 0; last < n; last++) {
            if (!(mask & (1 << last))) continue;
            if (dp[mask][last] == INF) continue;

            // Try to add a neighbor
            for (int nb : adj[last]) {
                if (mask & (1 << nb)) continue;
                int newMask = mask | (1 << nb);
                int reduction = 0;
                // Count shared faces with already placed cubes
                for (int d = 0; d < 6; d++) {
                    int nx = cubes[nb].x + dx[d];
                    int ny = cubes[nb].y + dy[d];
                    int nz = cubes[nb].z + dz[d];
                    auto it = idx.find({nx, ny, nz});
                    if (it != idx.end() && (mask & (1 << it->second))) {
                        reduction++;
                    }
                }
                int newSurface = dp[mask][last] + 6 - 2 * reduction;
                if (newSurface < dp[newMask][nb]) {
                    dp[newMask][nb] = newSurface;
                }
            }
        }
    }

    int answer = INF;
    for (int mask = 1; mask < fullMask; mask++) {
        if (__builtin_popcount(mask) == k) {
            // Check connectivity
            // BFS from any bit in mask
            int start = __builtin_ctz(mask);
            queue<int> q;
            vector<bool> visited(n, false);
            q.push(start);
            visited[start] = true;
            int count = 0;
            while (!q.empty()) {
                int u = q.front(); q.pop();
                count++;
                for (int v : adj[u]) {
                    if ((mask & (1 << v)) && !visited[v]) {
                        visited[v] = true;
                        q.push(v);
                    }
                }
            }
            if (count == k) {
                for (int last = 0; last < n; last++) {
                    if (mask & (1 << last)) {
                        answer = min(answer, dp[mask][last]);
                    }
                }
            }
        }
    }

    cout << answer << "\n";
    return 0;
}

