#include <bits/stdc++.h>
using namespace std;

/*
We are given n candidate positions of unit cubes on the integer grid.
Choose exactly k of them so that the chosen cubes form one 6-neighbour connected component,
and minimize total surface area of the union.

For a set S of cubes:
surface = 6*|S| - 2*(number of adjacent chosen pairs)

So for fixed k, minimizing surface is equivalent to maximizing the number of internal adjacencies.

We model the candidate cubes as a graph:
- vertices = given positions
- edge between two vertices iff their cubes share a face

We need a connected induced-by-choice vertex subset of size k maximizing number of edges inside it.

This is NP-hard in general graphs, but the intended constraints for this classical task are small enough
for dynamic programming over subsets / connected subsets. Since the statement excerpt omitted constraints,
we provide an exact solution using subset DP, suitable when n is small (which is the standard version).

Approach:
1. Build adjacency bitmasks.
2. Enumerate all subsets of size <= k.
3. DP over subsets:
   connected[mask] = whether mask induces a connected subgraph.
   edgesInside[mask] = number of graph edges with both ends in mask.
   For connected subsets of size k, compute surface.

Connectivity DP:
- A singleton is connected.
- For larger masks, remove the least significant bit v.
  mask is connected iff there exists u in (mask without v) such that:
    (mask without v) is connected and u adjacent to v
  This simple recurrence alone is insufficient because removing a specific bit may break connectivity.
So instead we use BFS expansion DP:
- Start all singletons as connected.
- For each connected mask with size < k, add any vertex outside mask adjacent to mask.
This enumerates exactly connected subsets.

We also maintain edgesInside incrementally:
edgesInside[newMask] = edgesInside[mask] + popcount(adj[v] & mask)

Use visited boolean for connected masks.

Finally answer min(6*k - 2*edgesInside[mask]) over connected masks of size k.

If no connected subset of size k exists, output 0 (fallback; usually problem guarantees existence).
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<long long> x(n), y(n), z(n);
    for (int i = 0; i < n; ++i) cin >> x[i] >> y[i] >> z[i];

    if (k == 0) {
        cout << 0 << '\n';
        return 0;
    }
    if (n == 0 || k > n) {
        cout << 0 << '\n';
        return 0;
    }

    vector<unsigned long long> adj(n, 0);
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            long long d = llabs(x[i] - x[j]) + llabs(y[i] - y[j]) + llabs(z[i] - z[j]);
            if (d == 1) {
                adj[i] |= (1ULL << j);
                adj[j] |= (1ULL << i);
            }
        }
    }

    if (n > 63) {
        // This exact subset solution requires small n.
        // The original task version has small constraints.
        // Still, handle gracefully.
        cout << 0 << '\n';
        return 0;
    }

    const unsigned long long TOTAL = 1ULL << n;
    vector<char> vis(TOTAL, 0);
    vector<unsigned short> sz(TOTAL, 0);
    vector<unsigned short> edgesInside(TOTAL, 0);

    queue<unsigned long long> q;
    for (int i = 0; i < n; ++i) {
        unsigned long long m = 1ULL << i;
        vis[m] = 1;
        sz[m] = 1;
        edgesInside[m] = 0;
        q.push(m);
    }

    int bestSurface = INT_MAX;

    while (!q.empty()) {
        unsigned long long mask = q.front();
        q.pop();
        int s = sz[mask];

        if (s == k) {
            int surface = 6 * k - 2 * edgesInside[mask];
            bestSurface = min(bestSurface, surface);
            continue;
        }

        unsigned long long neigh = 0;
        unsigned long long tmp = mask;
        while (tmp) {
            int v = __builtin_ctzll(tmp);
            tmp &= tmp - 1;
            neigh |= adj[v];
        }
        unsigned long long cand = neigh & ~mask;

        while (cand) {
            int v = __builtin_ctzll(cand);
            cand &= cand - 1;
            unsigned long long nmask = mask | (1ULL << v);
            if (!vis[nmask]) {
                vis[nmask] = 1;
                sz[nmask] = s + 1;
                edgesInside[nmask] = edgesInside[mask] + __builtin_popcountll(adj[v] & mask);
                q.push(nmask);
            }
        }
    }

    if (bestSurface == INT_MAX) bestSurface = 0;
    cout << bestSurface << '\n';
    return 0;
}

