    for start in range(n):
        chosen = {start}
        chosen_list = [start]
        adj_count = 0
        # For fast lookup of chosen set
        chosen_set = {start}
        # Potential expansion: (gain, node)
        # We'll recalc each step
        while len(chosen_list) < k:
            best_gain = -1
            best_node = -1
            for node in chosen_list:
                for nb in adj[node]:
                    if nb not in chosen_set:
                        # Count how many chosen neighbors this nb has
                        gain = 0
                        for nnb in adj[nb]:
                            if nnb in chosen_set:
                                gain += 1
                        if gain > best_gain:
                            best_gain = gain
                            best_node = nb
            if best_node == -1:
