                break
            chosen_set.add(best_node)
            chosen_list.append(best_node)
            adj_count += best_gain
        if len(chosen_list) == k:
            best_edges = max(best_edges, adj_count)

    # If nothing found, fallback (shouldn't happen with connected guarantee)
    if best_edges == -1:
        # Fallback: just take any k connected nodes via BFS
        for start in range(n):
            visited = set()
            q = [start]
            visited.add(start)
            edges = 0
            while q and len(visited) < k:
                u = q.pop(0)
                for v in adj[u]:
                    if v not in visited:
                        visited.add(v)
                        q.append(v)
                        # count edges from v to already visited
                        cnt = 0
                        for w in adj[v]:
                            if w in visited:
                                cnt += 1
                        edges += cnt
                        if len(visited) == k:
                            break
            if len(visited) == k:
                best_edges = max(best_edges, edges)

    print(6*k - 2*best_edges)

