            if nb in pos_set:
                adj[i].append(pos_set[nb])

    def count_adj(subset):
        s = set(subset)
        count = 0
        for i in subset:
            for j in adj[i]:
                if j in s and j > i:
                    count += 1
        return count

    def is_connected(subset):
        if len(subset) == 0:
            return True
        s = set(subset)
        visited = {subset[0]}
        queue = [subset[0]]
        while queue:
            cur = queue.pop()
            for nb in adj[cur]:
                if nb in s and nb not in visited:
                    visited.add(nb)
                    queue.append(nb)
        return len(visited) == len(subset)

    best = [0]

    # For small n, try all combinations
    if n <= 20:
        for combo in combinations(range(n), k):
            combo_list = list(combo)
            if is_connected(combo_list):
                c = count_adj(combo_list)
                if c > best[0]:
