                int dx = Math.abs(x[i]-x[j]), dy = Math.abs(y[i]-y[j]), dz = Math.abs(z[i]-z[j]);
                if (dx+dy+dz == 1) {
                    adj[i] |= (1<<j); adj[j] |= (1<<i);
                }
            }

        // dp[mask] = max shared faces for connected subset mask, -1 if not connected or invalid
        int[] dp = new int[1<<n];
        Arrays.fill(dp, -1);
        // Initialize single cubes
        for (int i = 0; i < n; i++) dp[1<<i] = 0;

        // Enumerate masks in order of popcount
        for (int mask = 1; mask < (1<<n); mask++) {
            if (dp[mask] < 0) continue;
            int pc = Integer.bitCount(mask);
            if (pc >= k) continue;
            // Try adding a neighbor
            int neighbors = 0;
            for (int i = 0; i < n; i++)
                if ((mask & (1<<i)) != 0) neighbors |= adj[i];
            neighbors &= ~mask;
            for (int nb = neighbors; nb != 0; nb &= nb-1) {
                int bit = nb & (-nb);
                int j = Integer.numberOfTrailingZeros(bit);
                int newMask = mask | bit;
                // Count shared faces: how many cubes in mask are adjacent to j
                int shared = Integer.bitCount(adj[j] & mask);
                int newVal = dp[mask] + shared;
                if (dp[newMask] < newVal) dp[newMask] = newVal;
            }
        }

        int maxShared = 0;
        for (int mask = 0; mask < (1<<n); mask++) {
            if (Integer.bitCount(mask) == k && dp[mask] >= 0)
                maxShared = Math.max(maxShared, dp[mask]);
        }

        System.out.println(6*k - 2*maxShared);
    }
}

